import java.util.*;
import java.io.*;

public class Main {
    static final int MOD_CONST = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n_size = Integer.parseInt(br.readLine().trim());

        // Initialize group_list
        List<List<Integer>> group_list = new ArrayList<>();
        for (int i = 0; i <= 8; i++) {
            group_list.add(new ArrayList<>());
        }

        int max_mask = 1 << n_size;
        int[] popcount_array = new int[max_mask];

        // Precompute group_list and popcount_array
        for (int idx_x = 0; idx_x < max_mask; idx_x++) {
            int count = Integer.bitCount(idx_x);
            popcount_array[idx_x] = count;
            group_list.get(count).add(idx_x);
        }

        // Read probabilities
        double[] prob_array = new double[n_size];
        for (int i = 0; i < n_size; i++) {
            st = new StringTokenizer(br.readLine());
            double prob = Double.parseDouble(st.nextToken());
            // Convert to modular form: prob * 570000004 % MOD_CONST
            prob_array[i] = (prob * 570000004) % MOD_CONST;
        }

        // Initialize dp_map_state
        // Using array of HashMaps for each state
        Map<Long, Long>[] dp_map_state = new HashMap[n_size + 1];
        for (int i = 0; i <= n_size; i++) {
            dp_map_state[i] = new HashMap<>();
        }
        // Starting state
        dp_map_state[0].put(1L, 1L);

        for (int idx_x = 0; idx_x < n_size; idx_x++) {
            Map<Long, Long> currentMap = dp_map_state[idx_x];
            for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                long state = entry.getKey();
                long count = entry.getValue();

                long[] aux_array = new long[n_size];
                Arrays.fill(aux_array, 0L);

                // Build aux_array
                for (int m : group_list.get(idx_x)) {
                    if (((state >> popcount_array[m]) & 1) != 0) {
                        for (int j = 0; j < n_size; j++) {
                            if (((m >> j) & 1) == 0) {
                                int new_mask = m | (1 << j);
                                aux_array[j] |= (1L << popcount_array[new_mask]);
                            }
                        }
                    }
                }

                // Iterate over all masks
                int total_masks = 1 << n_size;
                for (int msk = 0; msk < total_masks; msk++) {
                    long val_x = 1L;
                    long val_m = 0L;
                    for (int j = 0; j < n_size; j++) {
                        if (((msk >> j) & 1) != 0) {
                            val_m |= aux_array[j];
                            val_x = (val_x * (long)prob_array[j]) % MOD_CONST;
                        } else {
                            val_x = (val_x * ((MOD_CONST - (long)prob_array[j]) + 1) % MOD_CONST) % MOD_CONST;
                        }
                    }
                    long next_state = idx_x + 1;
                    long prev = dp_map_state[next_state].getOrDefault(val_m, 0L);
                    long new_val = (prev + count * val_x) % MOD_CONST;
                    dp_map_state[next_state].put(val_m, new_val);
                }
            }
        }

        // Output the result
        System.out.println(dp_map_state[n_size].getOrDefault(1L, 0L));
    }
}
